<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Ban, ChevronLeft, ChevronRight, Fingerprint, Flag, KeyRound, LogOut, Search, ShieldCheck, TimerOff, UserCheck, Users, X } from 'lucide-vue-next'
import dayjs from 'dayjs'
import adminHttp from '../api/adminHttp'
import { errorMessage } from '../api/http'

type AdminUser = { id:number;public_id:string;username:string;nickname:string;is_admin:boolean;account_status:string;muted_until?:string;violation_count:number;created_at:string }
type ReportItem = { id:number;target_type:string;reason_category:string;description?:string;status:string;created_at:string;reported_nickname:string;reported_username:string;reported_user_id:number;violation_count:number;account_status:string;muted_until?:string }
const router=useRouter();const adminUser=ref<any>(JSON.parse(localStorage.getItem('memospace_admin_user')||'{}'))
const activeTab=ref<'reports'|'users'>('reports');const users=ref<AdminUser[]>([]);const audits=ref<any[]>([]);const reports=ref<ReportItem[]>([])
const total=ref(0);const reportTotal=ref(0);const page=ref(1);const reportPage=ref(1);const size=20;const keyword=ref('');const reportFilter=ref('PENDING')
const loading=ref(true);const message=ref('');const modal=ref<'password'|'memo'|''>('');const selected=ref<AdminUser|null>(null);const value=ref('');const saving=ref(false)
const reportDetail=ref<any|null>(null);const reportBusy=ref(false);const evidenceUrls=ref<string[]>([])
const action=ref({removeContent:true,penalty:'WARNING',note:''})
const pages=computed(()=>Math.max(1,Math.ceil(total.value/size)));const reportPages=computed(()=>Math.max(1,Math.ceil(reportTotal.value/size)))
const reasonLabels:Record<string,string>={ILLEGAL:'违法或违禁',HARASSMENT:'骚扰辱骂',PORNOGRAPHY:'色情低俗',VIOLENCE:'暴力危险',FRAUD:'诈骗虚假',PRIVACY:'隐私泄露',OTHER:'其他'}
const auditLabel=(value:string)=>({RESET_PASSWORD:'重置密码',CHANGE_MEMO_ID:'修改 Memo ID',RESOLVE_REPORT:'处理举报',DISMISS_REPORT:'驳回举报',ACCOUNT_STATUS:'调整账号状态'}[value]||value)

const loadUsers=async()=>{const result=await adminHttp.get('/admin/users',{params:{keyword:keyword.value,page:page.value,size}});users.value=result.data.items;total.value=Number(result.data.total)}
const loadReports=async()=>{const result=await adminHttp.get('/admin/reports',{params:{status:reportFilter.value,page:reportPage.value,size}});reports.value=result.data.items;reportTotal.value=Number(result.data.total)}
const load=async()=>{loading.value=true;message.value='';try{const [, ,auditResult,meResult]=await Promise.all([loadUsers(),loadReports(),adminHttp.get('/admin/audit'),adminHttp.get('/admin/me')]);audits.value=auditResult.data;adminUser.value=meResult.data;localStorage.setItem('memospace_admin_user',JSON.stringify(meResult.data))}catch(error){message.value=errorMessage(error)}finally{loading.value=false}}
onMounted(load);onBeforeUnmount(()=>evidenceUrls.value.forEach(URL.revokeObjectURL))
const search=()=>{page.value=1;void loadUsers()};const turn=(next:number)=>{page.value=Math.min(pages.value,Math.max(1,next));void loadUsers()};const turnReports=(next:number)=>{reportPage.value=Math.min(reportPages.value,Math.max(1,next));void loadReports()}
const open=(kind:'password'|'memo',user:AdminUser)=>{modal.value=kind;selected.value=user;value.value=kind==='memo'?user.public_id:'';message.value=''}
const save=async()=>{if(!selected.value)return;saving.value=true;message.value='';try{if(modal.value==='password')await adminHttp.put(`/admin/users/${selected.value.id}/password`,{newPassword:value.value});else await adminHttp.put(`/admin/users/${selected.value.id}/memo-id`,{memoId:value.value});message.value=modal.value==='password'?`已为 ${selected.value.nickname} 设置临时密码。`:`${selected.value.nickname} 的 Memo ID 已更新。`;modal.value='';await load()}catch(error){message.value=errorMessage(error)}finally{saving.value=false}}
const closeReport=()=>{evidenceUrls.value.forEach(URL.revokeObjectURL);evidenceUrls.value=[];reportDetail.value=null}
const openReport=async(id:number)=>{reportBusy.value=true;try{const {data}=await adminHttp.get(`/admin/reports/${id}`);reportDetail.value=data;action.value={removeContent:true,penalty:'WARNING',note:''};evidenceUrls.value=[];for(const media of data.media||[]){const file=await adminHttp.get(String(media.content_url).replace(/^\/api\//,''),{responseType:'blob'});evidenceUrls.value.push(URL.createObjectURL(file.data))}}catch(error){message.value=errorMessage(error)}finally{reportBusy.value=false}}
const resolveReport=async(decision:'CONFIRM'|'DISMISS')=>{if(!reportDetail.value)return;reportBusy.value=true;try{await adminHttp.put(`/admin/reports/${reportDetail.value.id}/resolve`,{decision,removeContent:decision==='CONFIRM'&&action.value.removeContent,penalty:decision==='CONFIRM'?action.value.penalty:'NONE',note:action.value.note});message.value=decision==='DISMISS'?'举报已驳回。':'举报处理结果已生效并通知用户。';closeReport();await load()}catch(error){message.value=errorMessage(error)}finally{reportBusy.value=false}}
const setStatus=async(user:AdminUser,status:'ACTIVE'|'MUTE_7_DAYS'|'BAN')=>{if(!confirm(status==='BAN'?`确认封禁 ${user.nickname}？`:status==='MUTE_7_DAYS'?`确认禁言 ${user.nickname} 7 天？`:`确认解除 ${user.nickname} 的账号限制？`))return;try{await adminHttp.put(`/admin/users/${user.id}/status`,{action:status,note:'管理员从用户目录手动调整'});message.value='账号状态已更新。';await load()}catch(error){message.value=errorMessage(error)}}
const logout=()=>{localStorage.removeItem('memospace_admin_token');localStorage.removeItem('memospace_admin_user');router.push('/admin/login')}
</script>

<template>
  <main class="admin-page">
    <header class="admin-header"><router-link class="admin-brand" to="/admin"><span><ShieldCheck :size="20" /></span><div><b>拾光管理员中心</b><small>MEMOSPACE CONTROL ROOM</small></div></router-link><div class="admin-account"><span>{{adminUser.nickname||adminUser.username}}</span><router-link class="button" to="/home">返回网站</router-link><button class="icon-button" title="退出管理员登录" @click="logout"><LogOut :size="17" /></button></div></header>
    <div class="admin-wrap">
      <section class="admin-intro"><div><span class="eyebrow">PRIVATE COMMUNITY ADMINISTRATION</span><h1>社区安全与账号管理</h1><p>只查看用户主动举报的目标证据；管理员不能浏览其他私人 Memory、共同空间、聊天或媒体。</p></div><div class="admin-stats"><span><Flag :size="18" /><b>{{reportTotal}}</b><small>当前筛选举报</small></span><span><Users :size="18" /><b>{{total}}</b><small>全部用户</small></span></div></section>
      <nav class="admin-tabs"><button :class="{active:activeTab==='reports'}" @click="activeTab='reports'">举报中心</button><button :class="{active:activeTab==='users'}" @click="activeTab='users'">用户目录</button></nav>
      <p v-if="message" class="admin-message" role="status">{{message}}</p>

      <section v-if="activeTab==='reports'" class="admin-grid">
        <div class="admin-panel report-panel">
          <div class="admin-panel-heading"><div><span class="eyebrow">REPORT INBOX</span><h2>用户举报</h2></div><select v-model="reportFilter" @change="reportPage=1;loadReports()"><option value="PENDING">待处理</option><option value="RESOLVED">已确认</option><option value="DISMISSED">已驳回</option><option value="ALL">全部</option></select></div>
          <div v-if="loading" class="admin-empty">正在读取举报…</div>
          <div v-else-if="reports.length" class="report-list"><button v-for="item in reports" :key="item.id" @click="openReport(item.id)"><span class="report-icon"><Flag :size="16" /></span><div><strong>{{reasonLabels[item.reason_category]||item.reason_category}} · {{item.target_type==='MEMORY'?'记忆':'评论'}}</strong><p>被举报：{{item.reported_nickname}}（@{{item.reported_username}}）· 已确认违规 {{item.violation_count||0}} 次</p><small>{{dayjs(item.created_at).format('YYYY.MM.DD HH:mm')}} · {{item.status}}</small></div><em>查看详情</em></button></div>
          <div v-else class="admin-empty">当前没有符合条件的举报。</div>
          <footer class="admin-pagination"><span>第 {{reportPage}} / {{reportPages}} 页</span><div><button :disabled="reportPage<=1" @click="turnReports(reportPage-1)"><ChevronLeft :size="16" /></button><button :disabled="reportPage>=reportPages" @click="turnReports(reportPage+1)"><ChevronRight :size="16" /></button></div></footer>
        </div>
        <aside class="admin-panel audit-panel"><span class="eyebrow">AUDIT TRAIL</span><h2>最近管理记录</h2><div v-if="audits.length" class="audit-list"><article v-for="item in audits" :key="item.id"><i></i><div><b>{{auditLabel(item.action_type)}}</b><p>{{item.target_nickname||'未知用户'}} · {{item.detail}}</p><time>{{dayjs(item.created_at).format('MM.DD HH:mm')}}</time></div></article></div><p v-else class="admin-empty">还没有管理操作。</p></aside>
      </section>

      <section v-else class="admin-grid">
        <div class="admin-panel user-panel"><div class="admin-panel-heading"><div><span class="eyebrow">USER DIRECTORY</span><h2>用户列表</h2></div><form class="admin-search" @submit.prevent="search"><Search :size="15" /><input v-model="keyword" placeholder="昵称、用户名或完整 Memo ID" /><button>搜索</button></form></div>
          <div v-if="loading" class="admin-empty">正在读取用户…</div><div v-else-if="users.length" class="admin-user-list"><article v-for="user in users" :key="user.id" class="admin-user-row"><span class="admin-avatar">{{user.nickname?.slice(0,1)||'拾'}}</span><div class="admin-user-copy"><div><b>{{user.nickname}}</b><em v-if="user.is_admin">管理员</em><em v-else-if="user.account_status==='BANNED'" class="danger">已封号</em><em v-else-if="user.muted_until&&dayjs(user.muted_until).isAfter(dayjs())" class="warning">禁言中</em></div><p>@{{user.username}} · 违规 {{user.violation_count||0}} 次 · 注册于 {{dayjs(user.created_at).format('YYYY.MM.DD')}}</p><code>Memo ID {{user.public_id}}</code></div><div v-if="!user.is_admin" class="admin-user-actions"><button class="button" @click="open('memo',user)"><Fingerprint :size="14" />改 ID</button><button class="button" @click="open('password',user)"><KeyRound :size="14" />重置密码</button><button v-if="user.account_status==='BANNED'||(user.muted_until&&dayjs(user.muted_until).isAfter(dayjs()))" class="button" @click="setStatus(user,'ACTIVE')"><UserCheck :size="14" />解除</button><button v-else class="button" @click="setStatus(user,'MUTE_7_DAYS')"><TimerOff :size="14" />禁言</button><button v-if="user.account_status!=='BANNED'" class="button danger-button" @click="setStatus(user,'BAN')"><Ban :size="14" />封号</button></div></article></div><div v-else class="admin-empty">没有找到匹配的用户。</div>
          <footer class="admin-pagination"><span>第 {{page}} / {{pages}} 页</span><div><button :disabled="page<=1" @click="turn(page-1)"><ChevronLeft :size="16" /></button><button :disabled="page>=pages" @click="turn(page+1)"><ChevronRight :size="16" /></button></div></footer>
        </div><aside class="admin-panel audit-panel"><span class="eyebrow">ACCOUNT POLICY</span><h2>处罚说明</h2><p class="policy">警告会累计违规次数；禁言期间用户可以浏览，但不能发布 Memory、评论、共同空间留言或私聊；封号后现有登录令牌也会立即失效。</p></aside>
      </section>
    </div>

    <div v-if="modal" class="modal-backdrop" @click.self="modal='' "><section class="admin-action-modal"><header><div><span class="eyebrow">ADMIN ACTION</span><h2>{{modal==='password'?'重置临时密码':'修改 Memo ID'}}</h2></div><button class="icon-button" @click="modal='' "><X :size="17" /></button></header><p>正在修改：<b>{{selected?.nickname}}</b>（@{{selected?.username}}）</p><label class="field"><span>{{modal==='password'?'新的临时密码':'新的 12 位纯数字 Memo ID'}}</span><input v-model="value" :type="modal==='password'?'password':'text'" :maxlength="modal==='password'?72:12" /></label><small>{{modal==='password'?'管理员无法查看旧密码，用户登录后可自行修改。':'只修改对外代号，不改变原有好友、关系和 Memory。'}}</small><footer><button class="button" @click="modal=''">取消</button><button class="button primary" :disabled="saving||(modal==='password'?value.length<8:!/^\d{12}$/.test(value))" @click="save">{{saving?'正在保存…':'确认修改'}}</button></footer></section></div>

    <div v-if="reportDetail" class="modal-backdrop" @click.self="closeReport"><section class="report-detail-modal"><header><div><span class="eyebrow">REPORT #{{reportDetail.id}}</span><h2>{{reasonLabels[reportDetail.reason_category]}}举报详情</h2></div><button class="icon-button" @click="closeReport"><X :size="18" /></button></header><div class="report-meta"><span>举报人：{{reportDetail.reporter_nickname}}</span><span>被举报：{{reportDetail.reported_nickname}}（@{{reportDetail.reported_username}}）</span><span>已确认违规：{{reportDetail.violation_count||0}} 次</span></div><p v-if="reportDetail.description" class="report-description">用户说明：{{reportDetail.description}}</p><article class="evidence"><span class="eyebrow">REPORTED EVIDENCE</span><h3>{{reportDetail.target?.title||reportDetail.target?.memory_title||'被举报内容'}}</h3><p>{{reportDetail.target?.content}}</p><img v-for="url in evidenceUrls" :key="url" :src="url" alt="举报证据" /></article><template v-if="reportDetail.status==='PENDING'"><label class="check-row"><input v-model="action.removeContent" type="checkbox" />确认违规后删除这条{{reportDetail.target_type==='MEMORY'?'记忆':'评论'}}</label><label class="field"><span>账号处罚</span><select v-model="action.penalty"><option value="NONE">只记录违规</option><option value="WARNING">正式警告</option><option value="MUTE_7_DAYS">禁言 7 天</option><option value="BAN">直接封号</option></select></label><label class="field"><span>给用户的说明</span><textarea v-model="action.note" maxlength="500" rows="3"></textarea></label><footer><button class="button" :disabled="reportBusy" @click="resolveReport('DISMISS')">驳回举报</button><button class="button primary" :disabled="reportBusy" @click="resolveReport('CONFIRM')">{{reportBusy?'正在处理…':'确认违规并执行'}}</button></footer></template><p v-else class="resolved-note">处理结果：{{reportDetail.resolution_action}}<br />{{reportDetail.admin_note}}</p></section></div>
  </main>
</template>

<style scoped>
.admin-page{min-height:100vh;color:#292b33;background:#eeece7}.admin-header{height:78px;padding:0 max(26px,calc((100vw - 1320px)/2));display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d7d3cb;background:#f7f4ee}.admin-brand,.admin-account{display:flex;align-items:center;gap:11px}.admin-brand>span{width:40px;height:40px;display:grid;place-items:center;border-radius:13px;color:#fff;background:#3d4352}.admin-brand b,.admin-brand small{display:block}.admin-brand small{margin-top:3px;color:#81828a;font-size:8px;letter-spacing:.18em}.admin-account span{color:#686973;font-size:12px}.admin-account .button{min-height:36px;padding:0 13px;font-size:11px}.admin-wrap{max-width:1320px;margin:auto;padding:44px 26px 70px}.admin-intro{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:22px}.admin-intro h1{margin:8px 0;font-size:43px}.admin-intro p{max-width:720px;margin:0;color:#6e7079;line-height:1.7}.admin-stats{display:flex;gap:8px}.admin-stats>span{min-width:125px;padding:14px;display:grid;grid-template-columns:auto 1fr;gap:2px 9px;border-radius:17px;color:#fff;background:#424857}.admin-stats svg{grid-row:1/3}.admin-stats b{font-size:19px}.admin-stats small{font-size:9px;opacity:.7}.admin-tabs{margin-bottom:20px;display:flex;gap:5px}.admin-tabs button{padding:10px 17px;border:1px solid #d7d3cb;border-radius:12px;color:#6e7079;background:#faf8f3}.admin-tabs button.active{color:#fff;border-color:#424857;background:#424857}.admin-message{padding:12px 16px;border:1px solid #c9b7ae;border-radius:14px;color:#704f49;background:#f6ebe5;font-size:12px}.admin-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;align-items:start}.admin-panel{padding:25px;border:1px solid #d7d3cb;border-radius:25px;background:#faf8f3;box-shadow:0 14px 45px rgba(54,50,45,.08)}.admin-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:18px}.admin-panel-heading select,.report-detail-modal select{height:39px;padding:0 10px;border:1px solid #d2cec6;border-radius:12px;background:#fff}.admin-panel h2{margin:5px 0 0;font-size:22px}.admin-search{height:39px;display:flex;align-items:center;gap:8px;padding-left:11px;border:1px solid #d2cec6;border-radius:13px;background:#fff}.admin-search input{width:220px;border:0;outline:0;background:transparent}.admin-search button{height:100%;padding:0 13px;border:0;border-left:1px solid #ddd8d0;background:transparent}.admin-empty{padding:34px;text-align:center;color:#85858c;font-size:11px}.report-list{display:grid;gap:8px}.report-list>button{width:100%;padding:14px;display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:12px;border:1px solid #e0dcd5;border-radius:17px;color:#292b33;background:#fff;text-align:left}.report-icon{width:40px;height:40px;display:grid;place-items:center;border-radius:13px;color:#8d4f55;background:#f4e1e1}.report-list strong,.report-list p,.report-list small{display:block}.report-list p{margin:4px 0;color:#71727b;font-size:10px}.report-list small{color:#99989d;font-size:9px}.report-list em{color:#697183;font-size:10px;font-style:normal}.admin-user-list{display:grid;gap:8px}.admin-user-row{padding:14px;display:grid;grid-template-columns:45px minmax(0,1fr) auto;align-items:center;gap:12px;border:1px solid #e0dcd5;border-radius:17px;background:#fff}.admin-avatar{width:44px;height:44px;display:grid;place-items:center;border-radius:14px;color:#fff;background:linear-gradient(145deg,#7e6870,#4f596b);font:600 17px serif}.admin-user-copy>div{display:flex;align-items:center;gap:7px}.admin-user-copy em{padding:2px 6px;border-radius:999px;color:#744b55;background:#f1dde1;font-size:8px;font-style:normal}.admin-user-copy em.danger{color:#8b353b;background:#f6d9d9}.admin-user-copy em.warning{color:#7d5c20;background:#f6ebca}.admin-user-copy p{margin:3px 0;color:#85858c;font-size:9px}.admin-user-copy code{font-size:10px}.admin-user-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:5px}.admin-user-actions .button{min-height:34px;padding:0 9px;display:flex;align-items:center;gap:4px;font-size:9px}.danger-button{color:#8b353b;border-color:#ddb6b6}.admin-pagination{margin-top:16px;display:flex;justify-content:space-between;color:#85858c;font-size:10px}.admin-pagination div{display:flex;gap:5px}.admin-pagination button{width:32px;height:32px;display:grid;place-items:center;border:1px solid #d7d3cb;border-radius:10px;background:#fff}.audit-list{display:grid;margin-top:17px}.audit-list article{padding:12px 0;display:grid;grid-template-columns:9px 1fr;gap:11px;border-bottom:1px solid #e3ded7}.audit-list i{width:9px;height:9px;margin-top:5px;border-radius:50%;background:#718092}.audit-list p,.policy{color:#74757d;font-size:10px;line-height:1.65}.audit-list p{margin:4px 0}.audit-list time{font-size:9px;color:#999}.admin-action-modal,.report-detail-modal{width:min(650px,calc(100vw - 28px));max-height:90vh;overflow:auto;padding:27px;border-radius:25px;background:#faf8f3}.admin-action-modal{width:min(500px,calc(100vw - 28px))}.admin-action-modal header,.report-detail-modal header,.admin-action-modal footer,.report-detail-modal footer{display:flex;align-items:center;justify-content:space-between;gap:10px}.admin-action-modal h2,.report-detail-modal h2{margin:5px 0;font-size:25px}.admin-action-modal>p,.admin-action-modal>small{color:#70717a;font-size:11px}.admin-action-modal footer,.report-detail-modal footer{justify-content:flex-end;margin-top:20px}.report-meta{margin:18px 0;display:flex;flex-wrap:wrap;gap:7px}.report-meta span{padding:6px 9px;border-radius:9px;color:#656873;background:#ebe8e2;font-size:10px}.report-description,.resolved-note{padding:12px;border-radius:12px;color:#704f49;background:#f6ebe5;font-size:11px;line-height:1.6}.evidence{margin:16px 0;padding:18px;border:1px solid #ddd8d0;border-radius:18px;background:#fff}.evidence h3{margin:7px 0}.evidence p{white-space:pre-wrap;line-height:1.7}.evidence img{width:100%;max-height:420px;margin-top:10px;object-fit:contain;border-radius:14px;background:#eee}.check-row{margin:15px 0;padding:12px;display:flex;align-items:center;gap:9px;border:1px solid #ddd8d0;border-radius:13px;font-size:12px}@media(max-width:1000px){.admin-grid{grid-template-columns:1fr}.audit-panel{order:2}}@media(max-width:720px){.admin-header{padding:0 14px}.admin-account span,.admin-account .button,.admin-stats{display:none}.admin-wrap{padding:30px 14px}.admin-panel{padding:16px}.admin-panel-heading{align-items:stretch;flex-direction:column}.admin-search input{width:100%}.admin-user-row{grid-template-columns:40px 1fr}.admin-user-actions{grid-column:1/-1}.report-list>button{grid-template-columns:38px 1fr}.report-list em{display:none}}
</style>
